use std::io

fn digit_val(c: int) -> int {
    if c >= 48 && c <= 57 {
        return c - 48
    }
    if c >= 65 && c <= 90 {
        return c - 55
    }
    return c - 87
}

fn main() {
    let input = io::read_all()
    for line in input.split("\n") {
        let parts = line.trim().split(" ")
        let mut toks: Vec<string> = Vec::new()
        for p in parts {
            if p.len() > 0 {
                toks.push(p)
            }
        }
        if toks.len() < 3 {
            continue
        }
        let from = toks[1].parse::<int>().unwrap()
        let to = toks[2].parse::<int>().unwrap()
        let mut n: int = 0
        for b in toks[0].bytes() {
            n = n * from + digit_val(b as int)
        }
        if n == 0 {
            println("0")
            continue
        }
        let digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        let db = digits.bytes()
        let mut out: Vec<int> = Vec::new()
        while n > 0 {
            out.push(db[(n % to) as usize] as int)
            n = n / to
        }
        let mut s = ""
        let mut i = out.len()
        while i > 0 {
            i = i - 1
            s = s + digits.substring(out[i] as int, 0)
        }
        println(s)
    }
}

